      for (let j = 0; j < 16; j++) { g.fillStyle = j < n ? ink : soft; g.globalAlpha = j < n ? 1 : 0.5; g.fillRect(44 + j * 8.6, y + 1, 6.4, 11); } g.globalAlpha = 1;
      g.fillStyle = ink; g.textAlign = 'right'; g.fillText(String(Math.round(bars[i])).padStart(2, '0'), 208, y + 10);
